from decimal import ROUND_HALF_UP, Decimal


def order_total(qty, unit_price):
    """Total in euros for qty items at unit_price, rounded to cents.

    10 to 49 items get 5% off; 50 or more get 12% off. qty must be a
    positive int; unit_price is a str or Decimal and must not be negative.
    """
    if not isinstance(qty, int) or isinstance(qty, bool) or qty <= 0:
        raise ValueError("qty must be a positive integer")
    price = Decimal(str(unit_price))
    if price < 0:
        raise ValueError("unit_price must not be negative")
    total = price * qty
    if qty >= 50:
        total *= Decimal("0.88")
    elif qty >= 10:
        total *= Decimal("0.95")
    return total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
